function GreedyStep(A):
    n    <- |A|
    Bad  <- { c + d - b : b, c, d in A }          # <= n^3 values
    Half <- { (c + d)/2 : c, d in A, c + d even } # <= n^2 values
    for m = 0, 1, ..., n^3 + n^2 + n:
        if m not in A and m not in Bad and m not in Half:
            return m
    unreachable                                    # pigeonhole guarantees a survivor

function Build(n_terms):
    A <- []
    repeat n_terms times:  A <- A + [GreedyStep(A)]
    return A

