function IsDiffBh(A, h):
    M    <- all size-h multisets of A
    Seen <- empty map from integer to formal difference
    for s in M:
        for t in M:
            key    <- sum(s) - sum(t)
            formal <- canonical form of (multiplicities of s) - (multiplicities of t)
            if key in Seen and Seen[key] != formal:  return false
            Seen[key] <- formal
    return true

function AuditCollapse(family, max_h):
    for A in family, for h = 1..max_h:
        if IsDiffBh(A, h) != IsBh(A, 2h):  report mismatch; return false
    return true

